ALTER TABLE public.profiles ADD COLUMN last_seen timestamptz;
CREATE OR REPLACE FUNCTION public.touch_presence() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ UPDATE public.profiles SET last_seen = now() WHERE id = auth.uid(); $$;
REVOKE ALL ON FUNCTION public.touch_presence() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.touch_presence() TO authenticated;
CREATE TABLE public.password_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, reason text NOT NULL, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.password_requests TO authenticated;
GRANT ALL ON public.password_requests TO service_role;
ALTER TABLE public.password_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY password_request_read ON public.password_requests FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.has_role(auth.uid(), 'admin'));
CREATE POLICY password_request_insert ON public.password_requests FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND status = 'pending');
CREATE UNIQUE INDEX password_request_pending ON public.password_requests(user_id) WHERE status = 'pending';
CREATE TABLE public.prank_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, author_id uuid NOT NULL, effect text NOT NULL CHECK (effect IN ('confetti','flip','wiggle')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.prank_events TO authenticated;
GRANT ALL ON public.prank_events TO service_role;
ALTER TABLE public.prank_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY prank_read ON public.prank_events FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.has_role(auth.uid(), 'admin'));
CREATE POLICY prank_send ON public.prank_events FOR INSERT TO authenticated WITH CHECK (author_id = auth.uid() AND public.has_role(auth.uid(), 'admin'));
ALTER PUBLICATION supabase_realtime ADD TABLE public.prank_events;
ALTER PUBLICATION supabase_realtime ADD TABLE public.password_requests;